script.inlineScript:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */

/* the reason we are doing this backwards is because the tab is expecting
shouldHide to be true or false but we are passing in shouldShow from our script.
We might consider changing our script to pass shouldHide in the
future throught our app as we do this in multiple places*/
function evaluateProperty({
    api,
    helpers,
    context
}) {
    const hasAccountEntitlements = api.context.props.shouldShowAccountEntitlements;
    return !hasAccountEntitlements;
}

